<script>
const links=[["⌂","Overview"],["＋","Point of sale"],["▤","Orders"],["◈","Products"],["▦","Inventory"],["◎","Customers"],["↗","Analytics"]];
let cards=$state([["Revenue","—",""],["Orders","—",""],["Products","—",""],["Customers","—",""]]);\nlet dataLoaded=$state(false);\n$effect(()=>{fetch("/admin/coffeeos-data",{headers:{"Accept":"application/json"}}).then(r=>{if(!r.ok)throw new Error("Request failed");return r.json()}).then(data=>{cards=[["Revenue",new Intl.NumberFormat(undefined,{style:"currency",currency:"USD"}).format(data.summary.revenue),"Database total"],["Orders",String(data.summary.orders),"Database total"],["Products",String(data.summary.products),"Database total"],["Customers",String(data.summary.customers),"Database total"]];dataLoaded=true}).catch(()=>{dataLoaded=false})});
const orders=[["#1048","Alex Morgan","Flat white · Oat latte","Completed","10:42","$12.50"],["#1047","Sam Taylor","Cappuccino · Croissant","Completed","10:36","$9.80"],["#1046","Jordan Lee","Cold brew","Preparing","10:31","$6.25"],["#1045","Casey Smith","Matcha latte · Cookie","Completed","10:24","$11.40"]];
let active=$state("Overview"),search=$state(""),menu=$state(false);
</script>
<svelte:head><title>CoffeeOS</title></svelte:head>
<div class="co-shell"><aside class:co-open={menu} class="co-sidebar"><a class="co-brand" href="/admin"><span class="co-logo">☕</span><span><strong>CoffeeOS</strong><small>SHOP MANAGEMENT</small></span></a><div class="co-shop"><span class="co-shop-logo">B</span><span><strong>Bean & Bloom</strong><small>Downtown café</small></span></div><p class="co-label">WORKSPACE</p>{#each links as link}<button class:co-active={active===link[1]} class="co-link" onclick={()=>{active=link[1];menu=false}}><span>{link[0]}</span>{link[1]}</button>{/each}<div class="co-sidebar-bottom"><button class="co-link" onclick={()=>active="Settings"}>⚙ Settings</button><div class="co-help"><strong>Need a hand?</strong><p>Explore the CoffeeOS guide.</p></div><small>Admin User · Administrator</small></div></aside><main class="co-main"><header class="co-top"><button class="co-mobile" onclick={()=>menu=!menu}>☰</button><span>Workspace / <strong>{active}</strong></span><input placeholder="Search orders..." bind:value={search}/></header><div class="co-content"><div class="co-heading"><div><small>THURSDAY · NOVEMBER 26</small><h1>{active==="Overview"?"Good evening, Admin":active}</h1><p>Here’s what’s happening at your café today.</p></div><button class="co-primary" onclick={()=>active="Point of sale"}>＋ New order</button></div><div class="co-preview">✦ <strong>{dataLoaded?"Connected to Laravel":"Data connection"}</strong> — {dataLoaded?"summary values loaded from the database.":"loading database summary or unavailable."}</div><section class="co-stats">{#each cards as card}<article><small>{card[0]}</small><strong>{card[1]}</strong><span>{card[2]} <small>vs last week</small></span></article>{/each}</section><div class="co-panels"><section class="co-panel"><h2>Revenue overview</h2><p>Weekly performance · sample</p><strong class="co-big">$8,240.00 <span>↑ 12.8%</span></strong><svg viewBox="0 0 600 180" role="img" aria-label="Sample weekly revenue chart"><path d="M10 150 L90 120 L170 135 L250 80 L330 100 L410 35 L490 60 L590 18" fill="none" stroke="#66836c" stroke-width="4" stroke-linecap="round"/><path d="M10 150 L90 120 L170 135 L250 80 L330 100 L410 35 L490 60 L590 18 L590 180 L10 180Z" fill="#e6eee7"/></svg><div class="co-days">Mon　 Tue　 Wed　 Thu　 Fri　 Sat　 Sun</div></section><section class="co-panel"><h2>Top products</h2><p>Popular this week</p>{#each [["☕","Signature latte","142 sold"],["🥐","Butter croissant","96 sold"],["🍵","Iced matcha","74 sold"],["🧋","Cold brew","61 sold"]] as item}<div class="co-product"><span>{item[0]}</span><strong>{item[1]}</strong><small>{item[2]}</small></div>{/each}</section></div><section class="co-panel co-orders"><div class="co-order-heading"><div><h2>Recent orders</h2><p>Latest activity from your café</p></div><button onclick={()=>active="Orders"}>All orders →</button></div><div class="co-table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Status</th><th>Time</th><th>Total</th></tr></thead><tbody>{#each orders.filter(o=>!search||o.some(v=>v.toLowerCase().includes(search.toLowerCase()))) as o}<tr><td>{o[0]}</td><td>{o[1]}</td><td>{o[2]}</td><td><span class:co-done={o[3]==="Completed"} class="co-status">{o[3]}</span></td><td>{o[4]}</td><td>{o[5]}</td></tr>{/each}</tbody></table></div></section><footer>© 2026 CoffeeOS <span>Crafted for your café ♥</span></footer></div></main></div>